import React from 'react';
import { FaSearch } from 'react-icons/fa';

const Header = () => {
  return (
    <div className="header">
      <input type="text" className="search-bar" placeholder="Search..." />
      <FaSearch className="search-icon" />
    </div>
  );
};

export default Header;
